/* ==========================================================
    GSAP CONFIG
========================================================== */

gsap.registerPlugin(ScrollTrigger);

ScrollTrigger.config({

    ignoreMobileResize: true

});

ScrollTrigger.defaults({

    markers: false

});


/* ==========================================================
    COMMON SETTINGS
========================================================== */

const DEFAULT_DURATION = 1;
const DEFAULT_EASE = "power3.out";


/* ==========================================================
    HELPER
========================================================== */

function revealItems(selector, options = {}) {

    const items = gsap.utils.toArray(selector);

    if (!items.length) return;

    gsap.from(items, {

        opacity: 0,

        y: options.y ?? 50,

        scale: options.scale ?? 1,

        duration: options.duration ?? DEFAULT_DURATION,

        stagger: options.stagger ?? .15,

        ease: options.ease ?? DEFAULT_EASE,

        clearProps: "all",

        scrollTrigger: {

            trigger: options.trigger ?? items[0],

            start: options.start ?? "top 85%",

            once: true

        }

    });

}

/* ==========================================================
    HERO
========================================================== */

function initHeroAnimation() {

    const tl = gsap.timeline({

        defaults: {

            ease: DEFAULT_EASE

        }

    });

    tl.from(".hero__badge", {

        opacity: 0,

        y: -25,

        duration: .6

    })

    .from(".hero__title", {

        opacity: 0,

        y: 40,

        duration: .8

    }, "-=.3")

    .from(".hero__description", {

        opacity: 0,

        y: 30,

        duration: .7

    }, "-=.4")

    .from(".hero__actions", {

        opacity: 0,

        y: 30,

        duration: .7

    }, "-=.4")

    .from(".hero__mockup", {

        opacity: 0,

        scale: .9,

        y: 40,

        duration: 1

    }, "-=.5")

    .from(".hero__stat", {

        opacity: 0,

        y: 25,

        stagger: .15,

        duration: .6,

        clearProps: "all"

    }, "-=.4");

}

/* ==========================================================
    HERO FLOAT
========================================================== */

function initHeroFloat() {

    gsap.to(".hero__mockup", {

        y: -15,

        duration: 3,

        repeat: -1,

        yoyo: true,

        ease: "sine.inOut"

    });

}


/* ==========================================================
    HERO PARALLAX
========================================================== */

function initHeroParallax() {

    if (window.innerWidth < 992) return;

    gsap.to(".hero__mockup", {

        yPercent: 12,

        ease: "none",

        scrollTrigger: {

            trigger: ".hero",

            scrub: true

        }

    });

}


/* ==========================================================
    HERO INIT
========================================================== */

function initHero() {

    initHeroAnimation();

    initHeroFloat();

    initHeroParallax();

}

/* ==========================================================
    PROJECTS
========================================================== */

function initProjectsAnimation() {

    revealItems(".project-card", {

        trigger: ".projects",

        y: 60,

        stagger: 0.18

    });

    gsap.from(".projects .section-heading", {

        opacity: 0,

        y: 40,

        duration: .9,

        ease: DEFAULT_EASE,

        scrollTrigger: {

            trigger: ".projects",

            start: "top 80%",

            once: true

        }

    });

}


/* ==========================================================
    ABOUT
========================================================== */

function initAboutAnimation() {

    const tl = gsap.timeline({

        scrollTrigger: {

            trigger: ".about",

            start: "top 75%",

            once: true

        }

    });

    tl.from(".about__image", {

        x: -80,

        opacity: 0,

        duration: .9,

        ease: DEFAULT_EASE

    })

    .from(".about__content > *", {

        opacity: 0,

        y: 35,

        stagger: .15,

        duration: .6,

        clearProps: "all"

    }, "-=.4");

}


/* ==========================================================
    EXPERIENCE
========================================================== */

function initExperienceAnimation() {

    gsap.from(".experience .section-heading", {

        opacity: 0,

        y: 40,

        duration: .8,

        ease: DEFAULT_EASE,

        scrollTrigger: {

            trigger: ".experience",

            start: "top 80%",

            once: true

        }

    });

    revealItems(".timeline__item", {

        trigger: ".timeline",

        y: 60,

        stagger: .22

    });

    revealItems(".experience-stat", {

        trigger: ".experience__stats",

        y: 35,

        stagger: .12

    });

}


/* ==========================================================
    SERVICES
========================================================== */

function initServicesAnimation() {

    gsap.from(".services .section-heading", {

        opacity: 0,

        y: 40,

        duration: .8,

        ease: DEFAULT_EASE,

        scrollTrigger: {

            trigger: ".services",

            start: "top 80%",

            once: true

        }

    });

    revealItems(".service-card", {

        trigger: ".services__grid",

        y: 55,

        stagger: .16

    });

}


/* ==========================================================
    CONTENT
========================================================== */

function initContentAnimations() {

    initProjectsAnimation();

    initAboutAnimation();

    initExperienceAnimation();

    initServicesAnimation();

}

/* ==========================================================
    CREATIVE SHOWCASE
========================================================== */

function initCreativeAnimation() {

    gsap.from(".creative .section-heading", {

        opacity: 0,

        y: 40,

        duration: .8,

        ease: DEFAULT_EASE,

        scrollTrigger: {

            trigger: ".creative",

            start: "top 80%",

            once: true

        }

    });

    revealItems(".creative__filter", {

        trigger: ".creative__filters",

        y: 20,

        stagger: .08

    });

    revealItems(".creative-card", {

        trigger: ".creative__grid",

        y: 50,

        stagger: .08

    });

}

/* ==========================================================
    SKILLS
========================================================== */

function initSkillsAnimation() {

    gsap.from(".skills .section-heading", {

        opacity:0,

        y:40,

        duration:.8,

        ease:DEFAULT_EASE,

        scrollTrigger:{

            trigger:".skills",

            start:"top 80%",

            once:true

        }

    });

    revealItems(".skills-category",{

        trigger:".skills__wrapper",

        y:40,

        stagger:.18

    });

    revealItems(".skill-card",{

        trigger:".skills__wrapper",

        y:25,

        stagger:.05

    });

}

/* ==========================================================
    CONTACT
========================================================== */

function initContactAnimation(){

    gsap.from(".contact__card",{

        opacity:0,

        scale:.95,

        y:40,

        duration:1,

        ease:DEFAULT_EASE,

        clearProps:"all",

        scrollTrigger:{

            trigger:".contact",

            start:"top 80%",

            once:true

        }

    });

}


/* ==========================================================
    FOOTER
========================================================== */

function initFooterAnimation(){

    gsap.from(".footer",{

        opacity:0,

        y:40,

        duration:.8,

        ease:DEFAULT_EASE,

        scrollTrigger:{

            trigger:".footer",

            start:"top bottom",

            once:true

        }

    });

}


/* ==========================================================
    REDUCED MOTION
========================================================== */

function prefersReducedMotion(){

    return window.matchMedia(

        "(prefers-reduced-motion: reduce)"

    ).matches;

}


/* ==========================================================
    INIT GSAP
========================================================== */

function initGSAP(){

    if(prefersReducedMotion()){

        gsap.set("*",{

            clearProps:"all"

        });

        return;

    }

    initHero();

    initContentAnimations();

    initCreativeAnimation();

    initSkillsAnimation();

    initContactAnimation();

    initFooterAnimation();

    ScrollTrigger.refresh();

}


